def load_image(f):
    return Image.open(f).convert("RGB")


def embed_image(img):
    from src.features import embed_image as _e  # يتحمّل torch وقت الحاجة بس
    v = np.asarray(_e(img), dtype=np.float32).reshape(-1)
    return v / (np.linalg.norm(v) + 1e-9)


