def dominant_colors(img, k=5):
    px = np.asarray(img.convert("RGB").resize((96, 96))).reshape(-1, 3).astype(float)
    km = KMeans(k, n_init=3, random_state=0).fit(px)
    cnt = np.bincount(km.labels_, minlength=k)
    return [(tuple(int(v) for v in km.cluster_centers_[i]), float(cnt[i] / cnt.sum()))
            for i in np.argsort(-cnt)]


def pattern_stats(img):
    rgb = np.asarray(img.convert("RGB").resize((128, 128)), dtype=float)
    g = rgb.mean(axis=2) / 255
    gx, gy = np.abs(np.diff(g, axis=1))[:-1], np.abs(np.diff(g, axis=0))[:, :-1]
    rg, yb = rgb[..., 0] - rgb[..., 1], 0.5 * (rgb[..., 0] + rgb[..., 1]) - rgb[..., 2]
    colorful = np.hypot(rg.std(), yb.std()) + 0.3 * np.hypot(rg.mean(), yb.mean())
    return {
        "التماثل الأفقي": float(1 - np.abs(g - g[:, ::-1]).mean()),
        "التماثل الرأسي": float(1 - np.abs(g - g[::-1]).mean()),
        "كثافة الحواف": float(min(1, ((gx + gy) > 0.15).mean() * 2)),
        "التباين": float(min(1, g.std() * 3)),
        "تنوع الألوان": float(min(1, colorful / 100)),
    }


