def _get(url, **kw):
    import requests
    r = requests.get(url, headers=UA, timeout=20, **kw)
    r.raise_for_status()
    return r


def src_met(q, n):
    # v1/search اتقفل في 1 أكتوبر 2026، لازم v1.1
    ids = _get(f"{MET}/v1.1/search", params={"q": q, "hasImages": "true", "limit": n * 3}).json().get("objectIDs") or []

    def one(i):
        try:
            o = _get(f"{MET}/v1/objects/{i}").json()
            if o.get("isPublicDomain") and o.get("primaryImageSmall"):
                return dict(src="The Met", lic="CC0", title=o.get("title", ""), culture=o.get("culture") or o.get("country") or "",
                            date=o.get("objectDate", ""), url=o.get("objectURL", ""), img=o["primaryImageSmall"])
        except Exception:
            return None

    with cf.ThreadPoolExecutor(8) as ex:
        return [r for r in ex.map(one, ids[:n * 2]) if r][:n]


def src_aic(q, n):
    j = _get("https://api.artic.edu/api/v1/artworks/search", params={
        "q": q, "limit": n * 2, "fields": "id,title,image_id,place_of_origin,date_display,is_public_domain"}).json()
    return [dict(src="Art Institute of Chicago", lic="CC0", title=a.get("title", ""), culture=a.get("place_of_origin") or "",
                 date=a.get("date_display") or "", url=f"https://www.artic.edu/artworks/{a['id']}",
                 img=f"https://www.artic.edu/iiif/2/{a['image_id']}/full/843,/0/default.jpg")
            for a in j.get("data", []) if a.get("image_id") and a.get("is_public_domain")][:n]


def src_cma(q, n):
    j = _get("https://openaccess-api.clevelandart.org/api/artworks/", params={"q": q, "has_image": 1, "limit": n * 2}).json()
    out = []
    for a in j.get("data", []):
        im = ((a.get("images") or {}).get("web") or {}).get("url")
        if im and a.get("share_license_status") == "CC0":
            out.append(dict(src="Cleveland Museum of Art", lic="CC0", title=a.get("title", ""), culture=", ".join(a.get("culture") or []),
                            date=a.get("creation_date") or "", url=a.get("url") or "", img=im))
    return out[:n]


def src_commons(q, n):
    j = _get("https://commons.wikimedia.org/w/api.php", params={
        "action": "query", "generator": "search", "gsrsearch": f"{q} filetype:bitmap", "gsrnamespace": 6, "gsrlimit": n,
        "prop": "imageinfo", "iiprop": "url|extmetadata", "iiurlwidth": 400, "format": "json"}).json()
    out = []
    for p in ((j.get("query") or {}).get("pages") or {}).values():
        ii = (p.get("imageinfo") or [{}])[0]
        if ii.get("thumburl"):
            lic = ((ii.get("extmetadata") or {}).get("LicenseShortName") or {}).get("value", "see page")
            out.append(dict(src="Wikimedia Commons", lic=lic, title=p.get("title", "").replace("File:", ""), culture="", date="",
                            url=ii.get("descriptionurl", ""), img=ii["thumburl"]))
    return out[:n]


def src_openverse(q, n):
    j = _get("https://api.openverse.org/v1/images/", params={"q": q, "page_size": min(max(n * 2, 10), 40), "mature": "false"}).json()
    out = []
    for it in j.get("results", []):
        im = it.get("thumbnail") or it.get("url")
        if im:
            lic = f'{it.get("license", "")} {it.get("license_version", "")}'.strip() or "see source"
            out.append(dict(src="Openverse", lic=lic, title=it.get("title") or "Untitled", culture=it.get("provider") or "", date="",
                            url=it.get("foreign_landing_url") or it.get("detail_url") or "", img=im))
    return out[:n]


