def to_edges(im):
    from PIL import ImageFilter, ImageOps
    e = ImageOps.invert(ImageOps.autocontrast(im.convert("L").filter(ImageFilter.FIND_EDGES)))
    return e.convert("RGB")


def rank_by_image(recs, emb, bar, edges=False):
    cache = S.setdefault("emb_cache", {})
    tag = "#e" if edges else ""
    todo = [r for r in recs if r["img"] + tag not in cache]

    def dl(r):
        try:
            return r["img"], Image.open(io.BytesIO(_get(r["img"]).content)).convert("RGB")
        except Exception:
            return r["img"], None

    err = None
    with cf.ThreadPoolExecutor(8) as ex:
        for k, (u, im) in enumerate(ex.map(dl, todo), 1):
            bar.progress(k / max(1, len(todo)), text=f"Analyzing images {k}/{len(todo)}")
            if im is None or err:
                cache[u + tag] = None
                continue
            try:
                cache[u + tag] = embed_image(to_edges(im) if edges else im)
            except Exception as e:
                err = repr(e)[:200]
                cache[u + tag] = None
    if err:
        S["rank_err"] = err
    ok = [r for r in recs if cache.get(r["img"] + tag) is not None]
    if not ok:
        return recs  # model unavailable: show the results unranked instead of an error
    for r in ok:
        r["sim"] = float(cache[r["img"] + tag] @ emb)
    return sorted(ok, key=lambda r: -r["sim"])


