def clip_has():
    import importlib.util
    return importlib.util.find_spec("transformers") is not None


@st.cache_resource(show_spinner=False)
def _clip_holder():
    """Starts loading CLIP in a background thread once per app run (local files first, no waiting on the internet)."""
    import threading
    h = {"m": None, "p": None, "state": "loading", "err": ""}

    def work():
        try:
            from transformers import CLIPModel, CLIPProcessor
            name = "openai/clip-vit-base-patch32"
            try:
                m = CLIPModel.from_pretrained(name, local_files_only=True).eval()
                p = CLIPProcessor.from_pretrained(name, local_files_only=True)
            except Exception:
                m = CLIPModel.from_pretrained(name).eval()  # first time only: downloads ~600 MB
                p = CLIPProcessor.from_pretrained(name)
            h.update(m=m, p=p, state="ready")
        except Exception as e:
            h.update(state="failed", err=repr(e)[:200])

    threading.Thread(target=work, daemon=True).start()
    return h


def clip_load():
    h = _clip_holder()
    return (h["m"], h["p"]) if h["state"] == "ready" else None


if clip_has() and os.environ.get("HV_CLIP") != "0":
    _clip_holder()  # warm up as soon as the app opens


def clip_ok():
    if os.environ.get("HV_CLIP") == "0":
        return False
    if not clip_has() or clip_load() is None:
        return False
    if "clip_selftest" not in S:
        try:
            clip_texts(["test"])
            S["clip_selftest"] = True
        except Exception as e:
            S["clip_selftest"] = False
            S["rank_err"] = "CLIP: " + repr(e)[:160]
    return S["clip_selftest"]


def _nrm(x):
    return x / np.linalg.norm(x, axis=-1, keepdims=True)


def _clip_feat(m, kind, inp):
    """Projected CLIP embeddings that work on old and new transformers versions."""
    import torch
    with torch.no_grad():
        if kind == "text":
            o = m.text_model(input_ids=inp["input_ids"], attention_mask=inp.get("attention_mask"))
            pooled = getattr(o, "pooler_output", None)
            pooled = o[1] if pooled is None else pooled
            f = m.text_projection(pooled)
        else:
            o = m.vision_model(pixel_values=inp["pixel_values"])
            pooled = getattr(o, "pooler_output", None)
            pooled = o[1] if pooled is None else pooled
            f = m.visual_projection(pooled)
    return f.detach().cpu().numpy()


def clip_images(imgs):
    import torch
    m, p = clip_load()
    out = []
    for i in range(0, len(imgs), 16):
        with torch.no_grad():
            out.append(_clip_feat(m, "image", p(images=imgs[i:i + 16], return_tensors="pt")))
    return _nrm(np.concatenate(out))


def clip_texts(texts):
    import torch
    m, p = clip_load()
    with torch.no_grad():
        return _nrm(_clip_feat(m, "text", p(text=texts, return_tensors="pt", padding=True)))


def clip_words(img, draw=False, k=3):
    """يتعرّف على الرسمة/الصورة بالمعنى ويرجّع كلمات بحث."""
    key = f"clipv_{draw}"
    if key not in S:
        S[key] = clip_texts([("a simple line drawing of a " if draw else "a photo of a ") + v for v in CLIP_VOCAB])
    sims = clip_images([img])[0] @ S[key].T
    return [CLIP_VOCAB[i] for i in np.argsort(-sims)[:k]]


def clip_rank(recs, qvec=None, qtext=None, bar=None):
    cache = S.setdefault("clip_cache", {})
    todo = [r for r in recs if r["img"] not in cache]

    def dl(r):
        try:
            return r["img"], Image.open(io.BytesIO(_get(r["img"]).content)).convert("RGB")
        except Exception:
            return r["img"], None

    got = []
    with cf.ThreadPoolExecutor(8) as ex:
        for k, (u, im) in enumerate(ex.map(dl, todo), 1):
            if bar is not None:
                bar.progress(k / max(1, len(todo)), text=f"Analyzing images {k}/{len(todo)}")
            got.append((u, im))
    ok = [(u, im) for u, im in got if im is not None]
    if ok:
        for (u, _), v in zip(ok, clip_images([im for _, im in ok])):
            cache[u] = v
    recs = [r for r in recs if r["img"] in cache]
    if not recs:
        return []
    M = np.stack([cache[r["img"]] for r in recs])
    score = np.zeros(len(recs))
    if qvec is not None:
        score += M @ qvec
    if qtext is not None:
        score += 0.6 * (M @ qtext)
    lo, hi = score.min(), score.max()
    for r, sc in zip(recs, score):
        r["sim"] = float(0.5 + 0.49 * (sc - lo) / (hi - lo + 1e-9))
    return sorted(recs, key=lambda r: -r["sim"])


@st.cache_data(ttl=7 * 86400, show_spinner="Loading World Heritage Sites from Wikidata...")
def wd_sites():
    path = C.INDEX_DIR / "wd_sites.json"
    if path.exists():
        return json.load(open(path, encoding="utf-8"))
    j = _get("https://query.wikidata.org/sparql", params={"query": WD_Q, "format": "json"}).json()
    rows, seen = [], set()
    for b in j["results"]["bindings"]:
        qid = b["item"]["value"].rsplit("/", 1)[-1]
        if qid in seen:
            continue
        seen.add(qid)
        lon, lat = map(float, b["coord"]["value"][6:-1].split())
        im = b.get("image", {}).get("value", "").replace("http://", "https://")
        rows.append(dict(qid=qid, name=b["itemLabel"]["value"], country=b.get("countryLabel", {}).get("value", ""),
                         lat=lat, lon=lon, image=(im + ("&" if "?" in im else "?") + "width=480") if im else ""))
    C.INDEX_DIR.mkdir(exist_ok=True)
    json.dump(rows, open(path, "w", encoding="utf-8"), ensure_ascii=False)
    return rows


def site_card(s):
    return card(s["image"] or BLANK, _html.escape(s["country"] or "World"), _html.escape(s["name"][:42]), "UNESCO World Heritage · Wikidata")


def translate_query(q):
    if not re.search(r"[\u0600-\u06FF]", q):
        return q
    for ar, en in sorted(ARTR.items(), key=lambda kv: -len(kv[0])):
        q = q.replace(ar, en)
    return q


def add_history(q, srcs):
    try:
        h = S.get("history")
        if h is None:
            try:
                with open(HIST, encoding="utf-8") as f:
                    h = json.load(f) if HIST.exists() else []
            except Exception:
                h = []
            S.history = h
        h.insert(0, dict(q=q, src=srcs, ts=pd.Timestamp.now().strftime("%Y-%m-%d %H:%M")))
        del h[60:]
        C.INDEX_DIR.mkdir(parents=True, exist_ok=True)
        with open(HIST, "w", encoding="utf-8") as f:
            json.dump(h, f, ensure_ascii=False)
    except Exception:
        pass


def wiki_summary(title, lang="en"):
    from urllib.parse import quote
    return _get(f"https://{lang}.wikipedia.org/api/rest_v1/page/summary/{quote(title.replace(' ', '_'), safe='')}").json()


def circle_icon(im, size=96):
    from PIL import ImageDraw
    w, h = im.size
    s = min(w, h)
    im = im.crop(((w - s) // 2, (h - s) // 2, (w - s) // 2 + s, (h - s) // 2 + s)).resize((size - 8, size - 8))
    out = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    ring = Image.new("L", (size, size), 0)
    ImageDraw.Draw(ring).ellipse((0, 0, size - 1, size - 1), fill=255)
    out.paste((255, 255, 255, 255), mask=ring)
    m = Image.new("L", (size - 8, size - 8), 0)
    ImageDraw.Draw(m).ellipse((0, 0, size - 9, size - 9), fill=255)
    out.paste(im, (4, 4), m)
    b = io.BytesIO()
    out.save(b, "PNG", optimize=True)
    return "data:image/png;base64," + base64.b64encode(b.getvalue()).decode()


def build_landmark(row):
    try:
        j = wiki_summary(row[4])
        thumb = (j.get("thumbnail") or {}).get("source", "")
        co = j.get("coordinates") or {}
        icon = circle_icon(Image.open(io.BytesIO(_get(thumb).content)).convert("RGB")) if thumb else ""
        return row[1], dict(name=j.get("title", row[4]), extract=j.get("extract", ""), img=thumb, lat=co.get("lat"), lon=co.get("lon"),
                            url=((j.get("content_urls") or {}).get("desktop") or {}).get("page", ""), icon=icon)
    except Exception:
        return row[1], None


