def refine(recs, q):
    """يشيل المكرر ويرتّب النتايج حسب مطابقة كلمات البحث لعنوان القطعة."""
    toks = [t for t in re.findall(r"[a-z\u0600-\u06ff]{3,}", q.lower()) if t not in STOP]
    seen, out = set(), []
    for r in recs:
        if r["img"] in seen:
            continue
        seen.add(r["img"])
        txt = f'{r["title"]} {r["culture"]} {r["date"]}'.lower()
        r["_s"] = sum(t in txt for t in toks)
        out.append(r)
    good = [r for r in out if r["_s"] > 0]
    pool = good if len(good) >= 6 else out
    pool.sort(key=lambda r: -r["_s"])
    return pool


def country_data(iso):
    key, cc = (iso, L()), S.setdefault("cc", {})
    if key in cc:
        return cc[key]
    c = CBY[iso]
    try:
        summ = wiki_summary(c[3] if L() == "ar" else c[2], "ar" if L() == "ar" else "en").get("extract", "")
    except Exception:
        summ = ""
    try:
        names = WD_NAMES.get(iso, (c[2],))
        sites = [s for s in wd_sites() if s["country"] in names][:10]
    except Exception:
        sites = []
    cc[key] = dict(summary=summ, sites=sites)
    return cc[key]


def feature_data(iso, f):
    ck, cache = (iso, f[0]), S.setdefault("fc", {})
    if ck in cache:
        return cache[ck]
    q = f"{CBY[iso][2]} {f[3]}"
    with cf.ThreadPoolExecutor(4) as ex:
        fs = [ex.submit(fetch_source, s, q, n) for s, n in [("Wikimedia Commons", 12), ("The Met", 8), ("Art Institute of Chicago", 8), ("Cleveland Museum of Art", 8)]]
        res = [x.result()[0] for x in fs]
    cache[ck] = refine([x for tup in itertools.zip_longest(*res) for x in tup if x], q)
    return cache[ck]


def wheel_css(iso, feats, sel):
    """Each category is a real button clipped to a donut slice (percent-based polygon, so it scales)."""
    import math
    n, out = len(feats), []
    ro, ri, gap = 50, 30, math.radians(1.1)
    pal = ['#1E6FD9', '#F28C28', '#1557B0', '#E2475B', '#7A5AF0', '#12A39A']
    for i, f in enumerate(feats):
        a0 = -math.pi / 2 + 2 * math.pi * i / n + gap
        a1 = -math.pi / 2 + 2 * math.pi * (i + 1) / n - gap
        steps = 14
        pts = [(50 + ro * math.cos(a0 + (a1 - a0) * k / steps), 50 + ro * math.sin(a0 + (a1 - a0) * k / steps)) for k in range(steps + 1)]
        pts += [(50 + ri * math.cos(a1 - (a1 - a0) * k / steps), 50 + ri * math.sin(a1 - (a1 - a0) * k / steps)) for k in range(steps + 1)]
        poly = ", ".join(f"{x:.2f}% {y:.2f}%" for x, y in pts)
        am, rm = (a0 + a1) / 2, 40
        colr = pal[i % len(pal)]
        lx, ly = 50 + rm * math.cos(am), 50 + rm * math.sin(am)
        on = f[0] == sel
        dim = ""
        out.append(f".stApp .st-key-wheel .st-key-ft_{iso}_{f[0]} button {{clip-path: polygon({poly}); border: 0 !important; background: {'linear-gradient(135deg, #FFC94D, #F5A623)' if on else colr} !important;{dim}"
                   f"{'filter: brightness(1.12) drop-shadow(0 0 0 #fff);' if on else ''}}}"
                   f".st-key-ft_{iso}_{f[0]} button > div {{left: {lx:.2f}%; top: {ly:.2f}%;}}"
                   + (f".st-key-ft_{iso}_{f[0]} {{transform: translate({2.2 * math.cos(am):.2f}%, {2.2 * math.sin(am):.2f}%) scale(1.03);}}" if on else ""))
    return "".join(out)


