@st.cache_resource(show_spinner=False)
def _clf():
    from torchvision import models
    w = models.ResNet50_Weights.IMAGENET1K_V2
    return models.resnet50(weights=w).eval(), w.meta["categories"]


def guess_words(img, k=3):
    """يتعرّف على محتوى الصورة/الرسمة بنموذج ResNet50 ويرجّع أقرب كلمات للبحث."""
    import torch
    from src.features import to_tensor
    m, cats = _clf()
    with torch.no_grad():
        p = m(to_tensor(img).unsqueeze(0)).softmax(1)[0]
    return [cats[i].split(",")[0] for i in p.topk(k).indices.tolist()]


