def world_map(key, height=540):
    lm = landmarks()
    rows = [dict(iso=i, name=cname(CBY[i]), lat=d["lat"], lon=d["lon"], icon_data=dict(url=d["icon"], width=96, height=96, anchorY=48))
            for i, d in lm.items() if d.get("icon") and d.get("lat") is not None]
    if not rows:
        st.warning(T("Could not load landmarks. Check your internet connection.", "تعذّر تحميل المعالم. تأكد من الاتصال بالإنترنت."))
        return None
    import pydeck as pdk
    layers, geo = [], country_geojson()
    if geo:
        layers.append(pdk.Layer("GeoJsonLayer", data=geo, id="countries", pickable=True, stroked=True, filled=True,
                                get_fill_color=[139, 46, 28, 40], get_line_color=[139, 46, 28, 160], line_width_min_pixels=1,
                                auto_highlight=True, highlight_color=[201, 162, 74, 130]))
    layers.append(pdk.Layer("IconLayer", data=pd.DataFrame(rows), id="landmarks", get_icon="icon_data", get_position="[lon, lat]",
                            get_size=4, size_scale=11, pickable=True))
    deck = pdk.Deck(layers=layers, initial_view_state=pdk.ViewState(latitude=22, longitude=15, zoom=1.2, min_zoom=0.6),
                    map_style="road", tooltip={"text": "{name}"})
    ev = st.pydeck_chart(deck, on_select="rerun", selection_mode="single-object", key=key, height=height)
    sel = getattr(ev, "selection", None) or {}
    objs = sel.get("objects", {}) if hasattr(sel, "get") else {}
    for lst in objs.values():
        if lst:
            iso = lst[0].get("iso") or lst[0].get("id")
            if iso in CBY:
                return iso
    return None


