def page_ga():
    S.pic = "ga"
    hero(T("Global Archive", "الأرشيف العالمي"), T("Search live across museums and open archives worldwide. Nothing to download.", "ابحث مباشرة في المتاحف والأرشيفات المفتوحة حول العالم. بلا تنزيل أي بيانات."))
    if "ga_query" in S:
        S.ga_q = S.pop("ga_query")
    S.setdefault("ga_q", "textile")
    c1, c2 = st.columns([3, 1], gap="large")
    query = tin(c1, "Search heritage, crafts, motifs", key="ga_q")
    region = c2.selectbox("Region", list(REG_WORD))
    with st.container(key="srcpick_ga"):
        s1, s2 = st.columns([3, 1], gap="large")
        srcs = s1.multiselect(T("Sources", "المصادر"), list(SOURCES), default=list(SOURCES))
        n = s2.number_input(T("Results per source", "نتائج لكل مصدر"), min_value=3, max_value=30, value=12, step=3, key="ga_n")
    d2 = st.container()
    up = d2.file_uploader("Optional: rank results by visual similarity to your image", type=["png", "jpg", "jpeg", "webp"], key="ga_up")
    if st.button(":material/travel_explore: Search", key="ga_go", **ST) or S.pop("ga_auto", False):
        if not srcs or not query.strip():
            st.warning("Type a topic and choose at least one source.")
            return
        qq = f"{translate_query(query.strip())} {REG_WORD[region]}".strip()
        bar = st.progress(0, text="Searching sources...")
        with cf.ThreadPoolExecutor(4) as ex:
            res = list(ex.map(lambda s: fetch_source(s, qq, n), srcs))
        recs = refine([x for tup in itertools.zip_longest(*[r for r, _ in res]) for x in tup if x], qq)
        S.ga_fail = not recs and all(e for _, e in res)
        done = False
        if recs and clip_ok():
            try:
                recs = clip_rank(recs[:MAX_RANK], qvec=clip_images([load_image(up)])[0] if up is not None else None,
                                 qtext=clip_texts(["a photo of " + qq])[0], bar=bar)
                done = True
            except Exception as e:
                S["rank_err"] = "CLIP: " + repr(e)[:160]
        if not done and up is not None and recs:
            recs = rank_by_image(recs[:MAX_RANK], embed_image(load_image(up)), bar)
        bar.empty()
        S.ga_recs = recs
        add_history(query.strip(), srcs)
    recs = S.get("ga_recs")
    if recs is None:
        sec(f":material/category: {T('Start with a topic', 'ابدأ بموضوع')}")
        topic_tiles("gat", [("ga", T("Antiquities", "آثار"), "ancient antiquities"), ("comm", T("Textiles", "منسوجات"), "traditional textile"),
                            ("art", T("Pottery", "فخار"), "pottery vessel"), ("search", T("Masks", "أقنعة"), "ceremonial mask"),
                            ("crafts", T("Ceramics", "خزف"), "ceramic painted vase"), ("coll", T("Lamps & metal", "فوانيس ومعادن"), "lantern metalwork")])
        return
    if not recs:
        st.warning(T("Could not reach the sources right now. Check your connection.", "تعذّر الوصول للمصادر الآن. تأكد من اتصالك بالإنترنت.") if S.get("ga_fail") else T("No results. Try another word or more sources.", "لا توجد نتائج. جرّب كلمة أخرى أو مصادر أكثر."))
        return
    sec(f":material/image_search: {len(recs)} results")
    result_grid(recs, k="ga")
    st.caption("Sources: The Met, Art Institute of Chicago and Cleveland Museum of Art (CC0 objects only); Wikimedia Commons (licenses vary, check each page and credit the author).")


