FAV = C.INDEX_DIR / "favorites.json"


def favs():
    if "favs" not in S:
        S.favs = json.load(open(FAV, encoding="utf-8")) if FAV.exists() else []
    return S.favs


def toggle_fav(rec):
    f = favs()
    i = next((k for k, x in enumerate(f) if x["img"] == rec["img"]), None)
    if i is None:
        f.insert(0, {k: v for k, v in rec.items() if k != "sim" and not k.startswith("_")})
    else:
        del f[i]
    C.INDEX_DIR.mkdir(exist_ok=True)
    json.dump(f, open(FAV, "w", encoding="utf-8"), ensure_ascii=False)


def result_grid(recs, per_row=5, k="r"):
    saved = {x["img"] for x in favs()}
    idx = itertools.count()
    for r in range(0, len(recs), per_row):
        for col, m in zip(st.columns(per_row), recs[r:r + per_row]):
            sub = _html.escape(f'{m["lic"]} · {m["culture"]} {m["date"]}'.strip(" ·"))
            col.markdown(card(m["img"], SHORT.get(m["src"], m["src"]), _html.escape((m.get("title") or "")[:40]), sub,
                              max(0, min(100, m["sim"] * 100)) if "sim" in m else None), unsafe_allow_html=True)
            a, b = col.columns([2, 1])
            if m["url"]:
                a.markdown(f'<a href="{m["url"]}" target="_blank">{T("Source", "المصدر")}</a>', unsafe_allow_html=True)
            b.button("♥" if m["img"] in saved else "♡", key=f"sv_{k}_{next(idx)}", type="tertiary",
                     help=T("Save to My Collection", "احفظ في مجموعتي"), on_click=toggle_fav, args=(m,))


