def prep_sketch(img):
    """Crop the drawing to its content, center it on white with margin, and thicken thin strokes (sketches match much better)."""
    from PIL import ImageOps, ImageFilter
    g = np.asarray(img.convert("L"))
    ys, xs = np.where(g < 245)
    if len(xs) < 20:
        return img
    x0, x1, y0, y1 = xs.min(), xs.max(), ys.min(), ys.max()
    im = img.crop((x0, y0, x1 + 1, y1 + 1))
    side = int(max(im.size) * 1.18) + 2
    out = Image.new("RGB", (side, side), "white")
    out.paste(im, ((side - im.size[0]) // 2, (side - im.size[1]) // 2))
    out = out.filter(ImageFilter.MinFilter(3))
    return out.resize((448, 448), Image.LANCZOS)


def sketch_widget():
    d = C.INDEX_DIR / "sketch_component"
    d.mkdir(parents=True, exist_ok=True)
    (d / "index.html").write_text(SKETCH_HTML, encoding="utf-8")
    return components.declare_component("heritage_sketch", path=str(d))(key="sketch", default=None)


# ============ البحث بالصورة (رفع / كاميرا / رسم) على مصادر حية ============
def page_search():
    S.pic = "search"
    hero(T("Image Search", "البحث بالصورة"), T("Upload a photo, take one with your camera, or draw it. We search live museum collections.",
                                                  "ارفع صورة أو صوّرها بالكاميرا أو ارسمها، وسنبحث في مجموعات المتاحف مباشرة."))
    modes = {"up": T("Upload", "رفع صورة"), "cam": T("Camera", "الكاميرا"), "draw": T("Draw", "رسم")}
    S.setdefault("is_mode", "up")
    mode = st.radio("mode", list(modes), format_func=modes.get, horizontal=True, label_visibility="collapsed", key="is_mode")
    img = None
    if mode == "up":
        up = st.file_uploader(T("Photo", "الصورة"), type=["png", "jpg", "jpeg", "webp"], key="is_up")
        img = load_image(up) if up is not None else None
    elif mode == "cam":
        cam = st.camera_input(T("Take a photo", "صوّر القطعة"))
        img = load_image(cam) if cam is not None else None
    else:
        val = sketch_widget()
        if isinstance(val, str) and "," in val:
            img = prep_sketch(Image.open(io.BytesIO(base64.b64decode(val.split(",")[1]))).convert("RGB"))
        st.caption(T("Pick a color, draw with the pen or any geometric shape, color areas with the bucket, then press the magnifier icon. Writing what it is in the box below makes results much more accurate.",
                     "اختار اللون وارسم بالقلم أو بأي شكل هندسي، ولوّن بالدلو، وبعدين اضغط أيقونة العدسة. لو كتبت اسم القطعة في الخانة تحت النتائج هتبقى أدق بكتير."))
    if img is None:
        step_cards([("art", T("1. Upload, snap or draw", "١. ارفع أو صوّر أو ارسم"), "upload", "#1E6FD9"), ("buy", T("2. We search live museums", "٢. نبحث في المتاحف مباشرة"), "travel_explore", "#14A0B8"),
                    ("ga", T("3. See similar pieces", "٣. شاهد القطع المشابهة"), "photo_library", "#E2475B")])
    if not clip_has():
        st.caption(T("Tip: run  pip install transformers  once to understand what you draw or photograph and get much better matches.",
                     "نصيحة: نفّذ  pip install transformers  مرة واحدة ليفهم النظام ما ترسمه أو تصوّره ويعطي نتائج أدق بكثير."))
    with st.container(key="srcpick"):
        c1, c2 = st.columns([2, 1], gap="large")
        hint = c1.text_input(T("What is it? (helps the search)", "ما هي القطعة؟ (تساعد في البحث)"), placeholder=T("e.g. carpet, vase, mask, textile", "مثال: سجاد، فخار، قناع، نسيج"))
        n = c2.number_input(T("Results per source", "نتائج لكل مصدر"), min_value=3, max_value=30, value=6, step=3)
        srcs = st.multiselect(T("Sources", "المصادر"), list(SOURCES), default=list(SOURCES))
    if clip_has() and os.environ.get("HV_CLIP") != "0" and _clip_holder()["state"] == "loading":
        st.caption(T("The smart model is loading in the background; until it is ready the basic model is used.",
                     "النموذج الذكي بيتحمّل في الخلفية؛ لحد ما يجهز بيتم استخدام النموذج الأساسي."))
    if img is not None:
        a, b = st.columns([1, 2], gap="large")
        a.markdown(f"<img class='big' src='{pil_uri(img)}'>", unsafe_allow_html=True)
        b.markdown(swatches(dominant_colors(img)), unsafe_allow_html=True)
        b.markdown(bars(pattern_stats(img)), unsafe_allow_html=True)
    if st.button(":material/image_search: " + T("Search similar pieces", "ابحث عن قطع مشابهة"), key="is_go", **ST):
        if img is None or not srcs:
            st.warning(T("Add an image and choose at least one source.", "أضف صورة واختر مصدراً واحداً على الأقل."))
            return
        draw = mode == "draw"
        smart = clip_ok()
        try:
            if hint.strip():
                words = [translate_query(hint.strip())] + ([w for w in clip_words(img, draw, 2) if w not in hint] [:1] if smart and draw else [])
            else:
                words = clip_words(img, draw, 3) if smart else guess_words(img, 3)[:2]
        except Exception as e:
            smart = False
            S["rank_err"] = repr(e)[:200]
            words = [translate_query(hint.strip())] if hint.strip() else ["heritage craft"]
        S.is_words = words
        bar = st.progress(0, text=T("Searching sources...", "جاري البحث..."))
        with cf.ThreadPoolExecutor(6) as ex:
            res = list(ex.map(lambda t: fetch_source(t[0], t[1], n), [(s_, w) for w in words for s_ in srcs]))
        recs = refine([x for tup in itertools.zip_longest(*[r for r, _ in res]) for x in tup if x], " ".join(words))
        S.is_fail = not recs and all(e for _, e in res)
        S.is_recs = []
        if recs and smart:
            try:
                qt = clip_texts([("a photo of a museum object: " if draw else "a photo of ") + " ".join(words)])[0]
                S.is_recs = clip_rank(recs[:MAX_RANK], qvec=clip_images([img])[0] * (0.6 if draw else 1.0), qtext=qt * (1.6 if draw else 1.0), bar=bar)
            except Exception as e:
                S["rank_err"] = "CLIP: " + repr(e)[:160]
                smart = False
        if recs and not smart:
            S.is_recs = rank_by_image(recs[:MAX_RANK], embed_image(to_edges(img) if draw else img), bar, edges=draw)
        bar.empty()
        add_history(f"[image] {', '.join(words)}", srcs)
    recs = S.get("is_recs")
    if recs is None:
        return
    if S.get("is_words"):
        st.caption(T("We searched for: ", "بحثنا عن: ") + ", ".join(S.is_words))
    if not recs:
        st.warning(T("Could not reach the sources right now. Check your connection.", "تعذّر الوصول للمصادر الآن. تأكد من اتصالك بالإنترنت.") if S.get("is_fail") else T("No results. Try another hint.", "لا توجد نتائج. جرّب كلمة أخرى."))
        return
    sec(f":material/image_search: {len(recs)} " + T("most similar pieces", "قطعة مشابهة"))
    if S.get("rank_err"):
        st.caption("⚠ Image model problem (results shown with the backup model): " + str(S.rank_err))
    result_grid(recs, k="is")


def page_compare():
    S.pic = "cmp"
    hero(T("Compare Two Pieces", "مقارنة قطعتين"), T("See how similar two pieces are and which regions they share.", "شوف نسبة التشابه والمناطق المشتركة بين قطعتين."))
    imgs = []
    for n, col in enumerate(st.columns(2, gap="large")):
        up = col.file_uploader(T(f"Piece {n + 1}", f"القطعة {n + 1}"), type=["png", "jpg", "jpeg", "webp"], key=f"cu{n}")
        if up is not None:
            imgs.append(load_image(up))
    if len(imgs) < 2:
        st.info(T("Upload both pieces.", "ارفع القطعتين."), icon=":material/compare:")
        step_cards([("ga", T("Piece 1", "القطعة ١"), "looks_one", "#1E6FD9"), ("cmp", T("Similarity and shared regions", "التشابه والمناطق المشتركة"), "compare", "#1557B0"), ("crafts", T("Piece 2", "القطعة ٢"), "looks_two", "#E2475B")])
        return
    from src.explain import overlay, similarity_heatmap
    a, b = imgs
    ea, eb = embed_image(a), embed_image(b)
    sim = float(ea @ eb)
    m1, m2 = st.columns(2, gap="large")
    m1.metric(T("Similarity", "نسبة التشابه"), f"{sim * 100:.1f}%")
    m2.metric(T("Level (approx.)", "المستوى (تقريبي)"), T("High", "مرتفع") if sim > .8 else T("Medium", "متوسط") if sim > .65 else T("Low", "منخفض"))
    c1, c2 = st.columns(2, gap="large")
    c1.markdown(f"<img class='big' src='{pil_uri(overlay(a, similarity_heatmap(a, eb)))}'>", unsafe_allow_html=True)
    c2.markdown(f"<img class='big' src='{pil_uri(overlay(b, similarity_heatmap(b, ea)))}'>", unsafe_allow_html=True)
    st.caption(T("Red areas contributed most to the similarity.", "المناطق الحمراء هي اللي ساهمت أكتر في التشابه."))
    s1, s2 = st.columns(2, gap="large")
    s1.markdown(swatches(dominant_colors(a)), unsafe_allow_html=True)
    s2.markdown(swatches(dominant_colors(b)), unsafe_allow_html=True)


# ============ الحرفيون وأماكن الشراء (OpenStreetMap مباشرة) ============
OVERPASS = ["https://overpass-api.de/api/interpreter",
            "https://overpass.kumi.systems/api/interpreter",
            "https://overpass.private.coffee/api/interpreter",
            "https://overpass.openstreetmap.fr/api/interpreter"]
_OSM_CACHE = {}


def overpass_query(q):
    """Asks all map servers at the same time and returns the first good answer (max ~30 s)."""
    import requests
    if q in _OSM_CACHE:
        return _OSM_CACHE[q]

    def one(url):
        r = requests.post(url, data={"data": q}, headers=UA, timeout=(6, 25))
        if r.status_code != 200:
            raise Exception(f"{url.split('/')[2]} HTTP {r.status_code}")
        return r.json()

    ex = cf.ThreadPoolExecutor(len(OVERPASS))
    futs = [ex.submit(one, u) for u in OVERPASS]
    last = None
    try:
        for f in cf.as_completed(futs, timeout=30):
            try:
                j = f.result()
                _OSM_CACHE[q] = j
                return j
            except Exception as e:
                last = e
    except cf.TimeoutError:
        pass
    finally:
        ex.shutdown(wait=False, cancel_futures=True)
    raise RuntimeError("busy") from last
SHOP_RE = "^(craft|gift|art|antiques|carpet|fabric|textile|jewelry|ceramics|pottery|souvenir|boutique)$"


def geocode(q):
    errs = []
    try:
        j = _get("https://nominatim.openstreetmap.org/search", params={"q": q, "format": "json", "limit": 1}).json()
        if j:
            return float(j[0]["lat"]), float(j[0]["lon"])
    except Exception as e:
        errs.append("nominatim: " + repr(e)[:150])
    # backup geocoder (Open-Meteo), used when Nominatim is blocked or busy
    name = q.split(",")[0].strip()
    try:
        j = _get("https://geocoding-api.open-meteo.com/v1/search", params={"name": name, "count": 1}).json()
        r = (j.get("results") or [None])[0]
        if r:
            return float(r["latitude"]), float(r["longitude"])
    except Exception as e:
        errs.append("open-meteo: " + repr(e)[:150])
    if errs:
        raise RuntimeError(" | ".join(errs))
    return None


NOMI_KW = {"artisans": ["craft", "pottery", "workshop", "weaver", "carpenter", "jeweller", "glass", "leather"],
           "buy": ["craft shop", "gift shop", "souvenir", "antique shop", "bazaar", "market", "art gallery", "jewelry shop", "carpet shop"]}


def nominatim_places(lat, lon, kind, r):
    """Backup when all map servers are busy: ask the OpenStreetMap search instead (fewer results, but it answers)."""
    import time
    d = r / 111000
    box = f"{lon - d},{lat + d},{lon + d},{lat - d}"
    ok = {"craft"} if kind == "artisans" else {"shop", "tourism", "amenity"}
    out, seen = [], set()
    for kw in NOMI_KW["artisans" if kind == "artisans" else "buy"][:5]:
        try:
            j = _get("https://nominatim.openstreetmap.org/search", params={"q": kw, "format": "jsonv2", "limit": 40, "viewbox": box,
                                                                          "bounded": 1, "extratags": 1, "addressdetails": 1}).json()
        except Exception:
            continue
        for e in j:
            cat, typ, nm = e.get("category", ""), e.get("type", ""), e.get("name") or ""
            if not nm or nm in seen or (cat not in ok and not (kind == "artisans" and cat == "shop" and typ in ("craft", "pottery"))):
                continue
            seen.add(nm)
            x, a = e.get("extratags") or {}, e.get("address") or {}
            out.append(dict(name=nm, kind=typ.replace("_", " "), lat=float(e["lat"]), lon=float(e["lon"]),
                            addr=", ".join(v for v in [a.get("road"), a.get("city") or a.get("town") or a.get("suburb")] if v),
                            web=x.get("website") or x.get("contact:website") or "", phone=x.get("phone") or x.get("contact:phone") or "",
                            hours=x.get("opening_hours", "")))
        if len(out) >= 20:
            break
        time.sleep(1)  # Nominatim allows 1 request per second
    return out


def osm_places(lat, lon, kind, r):
    if kind == "artisans":
        body = f'nwr["craft"]["name"](around:{r},{lat},{lon});'
    else:
        body = (f'nwr["shop"~"{SHOP_RE}"]["name"](around:{r},{lat},{lon});nwr["amenity"="marketplace"]["name"](around:{r},{lat},{lon});'
                f'nwr["tourism"="gallery"]["name"](around:{r},{lat},{lon});')
    try:
        j = overpass_query(f"[out:json][timeout:25];({body});out center 80;")
    except Exception:
        return nominatim_places(lat, lon, kind, r)
    out = []
    for e in j.get("elements", []):
        t, c = e.get("tags", {}), e.get("center") or {}
        la, lo = e.get("lat", c.get("lat")), e.get("lon", c.get("lon"))
        if la is None or lo is None:
            continue
        out.append(dict(name=t.get("name", ""), kind=(t.get("craft") or t.get("shop") or t.get("amenity") or t.get("tourism") or "").replace("_", " "),
                        lat=la, lon=lo, addr=", ".join(x for x in [t.get("addr:street"), t.get("addr:city")] if x),
                        web=t.get("website") or t.get("contact:website") or "", phone=t.get("phone") or t.get("contact:phone") or "",
                        hours=t.get("opening_hours", "")))
    return out


def _dk(h):
    """Dark shade of an accent color, used for headings/links on the tinted cards."""
    r, g, b = (int(h[i:i + 2], 16) for i in (1, 3, 5))
    return "#%02X%02X%02X" % (round(r * .45), round(g * .45), round(b * .45))


PLACE_PAL = [("#C4DAF5", "#83B0EA", "#1E6FD9"), ("#F9DEC3", "#F2B981", "#E8801A"), ("#C0E2E0", "#7AC1BD", "#0E8F87"),
             ("#C2D3EA", "#7EA3D4", "#1557B0"), ("#F5D4C8", "#EAA38A", "#D9582B"), ("#C9E1D3", "#8CBFA3", "#2E8B57")]


def _hex_rgb(h):
    h = h.lstrip("#")
    return [int(h[i:i + 2], 16) for i in (0, 2, 4)]


def places_map(rows):
    """Colorful street map (Carto Voyager, similar look to Google Maps) with one colored marker per place."""
    import math
    import pydeck as pdk
    df = pd.DataFrame([dict(name=p["name"][:50], kind=p["kind"] or "place", lat=p["lat"], lon=p["lon"],
                            color=_hex_rgb(PLACE_PAL[k % len(PLACE_PAL)][2])) for k, p in enumerate(rows)])
    lat, lon = float(df.lat.mean()), float(df.lon.mean())
    span = max(float(df.lat.max() - df.lat.min()), float(df.lon.max() - df.lon.min()), 0.01)
    zoom = max(3.0, min(15.0, math.log2(360 * 1.37 / (span * 1.5))))
    layer = pdk.Layer("ScatterplotLayer", data=df, get_position="[lon, lat]", get_fill_color="color", get_line_color=[255, 255, 255],
                      stroked=True, line_width_min_pixels=2, get_radius=60, radius_min_pixels=8, radius_max_pixels=20, pickable=True)
    deck = pdk.Deck(layers=[layer], initial_view_state=pdk.ViewState(latitude=lat, longitude=lon, zoom=zoom),
                    map_style="road", tooltip={"text": "{name}\n{kind}"})
    st.pydeck_chart(deck, height=460)


