CRAFT_IMG = C.INDEX_DIR / "craft_images.json"


def craft_images(pairs):
    d = S.get("craft_imgs") or (json.load(open(CRAFT_IMG, encoding="utf-8")) if CRAFT_IMG.exists() else {})
    todo = [p for p in pairs if p[0] not in d]
    if todo:
        def one(p):
            try:
                r = src_commons(p[1] + " craft", 3)
                return p[0], (r[0]["img"] if r else "")
            except Exception:
                return p[0], None
        with st.spinner(T("Loading craft photos...", "جاري تحميل صور الحرف...")):
            with cf.ThreadPoolExecutor(6) as ex:
                for iso, u in ex.map(one, todo):
                    if u is not None:
                        d[iso] = u
        C.INDEX_DIR.mkdir(exist_ok=True)
        json.dump(d, open(CRAFT_IMG, "w", encoding="utf-8"), ensure_ascii=False)
    S.craft_imgs = d
    return d


